#!/usr/bin/env bash
# force-help.sh — 매 턴 SCV 를 준비시키는 preflight 의 문자열부.
#
# 이름의 유래는 "강제" 지만, 강제하는 것은 더 이상 없다. 0.39.0 은 응답 종료 시점에
# 모델을 되돌려 세워 help 호출을 강제했고, 그것이 비쌌다 — 되돌림은 모델이 답을 다
# 쓴 뒤에 걸리므로 되돌릴 때마다 답이 통째로 다시 생성됐다. 되돌림 한 번의 값은
# 모델 턴 하나이고, 그것은 진단 3KB 를 주입하는 값보다 훨씬 크다.
#
# 목적을 잘못 잡은 것이 근본 원인이었다. 목적은 "스킬이 호출되는 것" 이 아니라
# "이 턴에 SCV 의 현재 상태가 들어와 있는 것" 이었다. 호출은 수단이었을 뿐인데
# 그 수단을 강제하느라 목적보다 비싼 값을 치렀다. 그래서 지점을 턴의 시작으로
# 옮겼다: 프롬프트 훅이 진단을 직접 주입하면 목적이 곧바로 달성되고, 강제할 것이
# 남지 않는다.
#
# 여기 있는 것: 스위치 해석, 진단 잘라내기, 표시줄, 분류 지침.
# 여기 없는 것: 파일 읽기·쓰기·표준출력·명령 실행. 전부 훅이 한다.

# @pure
# 스위치 해석 — off 만 끈다. 값이 없거나 다른 값이면 켜져 있다. 기존 두 스위치
# (쉬운말·항상 라우팅)와 같은 규칙이라야 사용자가 규칙을 하나만 기억한다.
scv_force_switch() {
  local v="${1:-}"
  v="${v//[[:space:]]/}"
  v="${v//\"/}"
  v="${v//\'/}"
  # 대소문자는 case 로 본다. ${v,,} 는 bash 4 부터라 오래된 셸에서 조용히 깨진다.
  case "$v" in
    [Oo][Ff][Ff]) printf 'off' ;;
    *)            printf 'on'  ;;
  esac
}

# @pure
# 상태 점검 출력에서 진단부터 끝까지만 남긴다.
#
# 앞부분은 SCV 개요와 명령 목록이고 매 턴 글자 하나 다르지 않다 (실측 2,823바이트).
# 그것을 매 턴 실어 보내는 것은 같은 문장을 반복해서 사는 것과 같다. 뒤쪽 진단
# (실측 3,148바이트)만 이 턴에 대해 새로운 정보다.
#
# 표지를 못 찾으면 자르지 않고 전체를 돌려준다 — 점검 출력 형식이 바뀌었을 때
# 반쪽을 싣느니 많이 싣는 편이 낫다. 입력은 표준입력으로 받는다.
scv_force_trim_diagnosis() {
  # 전부 초기화한다 — 훅은 set -u 아래에서 돌고, 빈 채로 참조하면 그 자리에서 죽는다.
  local all="" line="" out="" seen=0
  while IFS= read -r line; do
    all="${all}${line}"$'\n'
    if [[ "$seen" == "0" && "$line" == *"Current project diagnosis"* ]]; then
      seen=1
    fi
    [[ "$seen" == "1" ]] && out="${out}${line}"$'\n'
  done
  if [[ "$seen" == "1" ]]; then printf '%s' "$out"; else printf '%s' "$all"; fi
}

# @pure
# 자동 갱신 보고 고르기 — 점검 스크립트의 stderr 에서 템플릿 갱신에 관한 줄만 남긴다.
#
# 왜 필요한가: 갱신은 이미 자동으로 돈다. `scv_autosync` 가 도장을 비교해 다르면
# sync 를 직접 실행하고, 결과를 stderr 로 알린다. 그런데 훅이 점검 스크립트를
# 2>/dev/null 로 불러 그 보고를 통째로 버렸다. 갱신은 됐는데 화면에 아무 증거가
# 남지 않으니, 사용자는 "정말 됐나" 싶어 sync 를 손으로 한 번 더 친다. 이 함수가
# 그 증거를 돌려준다.
#
# 왜 전부 싣지 않는가: 같은 stderr 로 설정 파일 생성·비밀 파일·심볼릭 링크 같은
# 다른 보고도 나온다. 한 줄 문제를 고치려다 매 턴 그 전부를 쏟으면 preflight 블록의
# 신뢰가 무너진다. 그래서 고른 줄만 싣는다.
#
# 고르는 규칙은 두 줄이다 —
#   1. `scv: ` 로 시작하고 template 또는 workflow docs 를 말하는 줄만 남긴다.
#      템플릿 보고는 전부 둘 중 하나를 말하고, 설정 계열 보고는 둘 다 말하지 않는다.
#   2. 그 줄 바로 뒤에 붙는 들여쓴 DIRTY/WARN/UNKNOWN 줄은 부분 갱신의 본문이므로
#      함께 남긴다. 어느 파일이 거부됐는지가 그 줄에만 있다.
# 그 외의 줄에서는 남기기를 끈다 — 관계없는 보고가 뒤따라 새지 않게 한다.
#
# 입력은 표준입력, 출력은 0줄 또는 그 이상. 갱신할 것이 없으면 아무 것도 내지
# 않는다 — 침묵이 기본값이다.
scv_force_refresh_note() {
  local line="" out="" keep=0
  while IFS= read -r line; do
    case "$line" in
      "scv: "*)
        case "$line" in
          *template*|*TEMPLATE*|*"workflow docs"*) keep=1 ;;
          *)                                       keep=0 ;;
        esac
        ;;
      "  DIRTY"*|"  WARN"*|"  UNKNOWN"*) : ;;
      *) keep=0 ;;
    esac
    [[ "$keep" == "1" ]] && out="${out}${line}"$'\n'
  done
  printf '%s' "$out"
}

# @pure
# 화면 표시줄 — 강제가 아니라 준비가 켜져 있다는 사실을 한 줄로.
# 인자: on|off. 사용자가 "되는지 안 되는지 구분이 안 간다" 고 한 것이 이 줄이 있는 이유이고,
# 되돌림을 걷어낸 뒤에도 그 요구는 그대로 남아 있으므로 이 줄도 남는다.
scv_force_banner() {
  [[ "${1:-off}" == "on" ]] || return 0
  printf '[SCV preflight] 이번 턴의 프로젝트 상태를 함께 실었다.'
}

# @pure
# 매 턴 맨 앞에 실리는 지시 블록.
#
# 0.41.0 은 이 지시를 맨 앞으로 옮기고 조건문을 명령으로 바꿨는데도 호출이 되지
# 않았다. 남아 있던 원인은 **세 갈래 그 자체**였다.
#
# 블록이 "셋 중 하나를 고르고, 고른 것을 실행하라" 고 말했다. 고르는 일이 행동보다
# 앞에 있었고, 셋째 갈래는 "아무 것도 부르지 말라" 였다 — 즉 **아무 것도 하지 않는
# 것이 정답인 경우가 명시돼 있었다.** 애매한 입력 앞에서 두 갈래(호출)와 한
# 갈래(침묵) 중 침묵이 언제나 더 싸다. 볼륨을 올려도 이 비대칭은 남는다.
#
# 그래서 판단을 옮겼다. 여기는 조건 없는 명령 하나가 되고, "부를 필요가 있었는지"
# 는 help 가 인자를 손에 쥐고 판단한다. 모델에게 선택지가 없으므로 샐 곳도 없다.
#
# 옮기면서 한 번 더 걸러야 했다. 처음 안은 help 안에 "남길 논의 없음 → 아무 것도
# 쓰지 않고 끝" 갈래를 두는 것이었는데, 그것은 **출구를 여기서 저기로 옮겼을 뿐
# 출구 자체는 살려 둔 것**이다. 같은 구멍이 자리만 바꾼다. 그래서 그 갈래도 두지
# 않는다 — help 는 돌려보내지 않고 항상 기록한다.
#
# 예외는 둘뿐이고, 둘 다 분류가 아니라 정의상 해당 없음이다. 이미 SCV 액션이 도는
# 턴에서 다시 부르면 자기 자신을 부른다. 사람이 쓰지 않은 자동 알림에는 사람의
# 요구가 없다.
#
# 남기는 것 둘: 왜 불러야 하는지의 **이유**(명령은 무시될 수 있지만 사실은 남는다),
# 그리고 재조회 금지를 **진단으로만** 좁힌 문장(0.40.0 의 자기모순을 닫은 자리다).
scv_force_routing() {
  printf '%s\n' "════════ SCV: 이 턴의 첫 행동 ════════"
  printf '%s\n' "답을 쓰기 전에, 이 메시지 전문을 인자로 하여 SCV help 액션을 지금 호출하라."
  printf '%s\n' "다른 도구보다 먼저. 조사·파일 읽기·코드 수정보다 먼저."
  printf '%s\n' "**판단하지 말고 부르라** — 부를 필요가 있었는지는 help 가 판단한다."
  printf '%s\n' ""
  printf '%s\n' "부르지 않는 경우는 둘뿐이다: 이 턴에 **이미 SCV 액션이 실려 있거나**,"
  printf '%s\n' "**사람이 쓰지 않은 자동 알림**이거나. 그 외에는 예외가 없다."
  printf '%s\n' ""
  printf '%s\n' "부르지 않으면 **이 논의는 어디에도 남지 않는다.** help 는 오간 말을 파일로"
  printf '%s\n' "적어 세션이 끝나도 살아남게 하고, 그 파일이 나중에 계획서의 근거가 된다."
  printf '%s\n' "아래 진단은 그 일을 대신하지 못한다 — 진단은 상태일 뿐 논의가 아니다."
  printf '%s\n' ""
  printf '%s\n' "아래 진단은 이번 턴의 프로젝트 상태다. **상태를 다시 조회하지 않는 데에만**"
  printf '%s' "쓰라 — 진단을 받은 것은 호출을 건너뛸 이유가 되지 않는다. 끄는 법: scv/scv_settings.json SCV_ALWAYS_ON=off."
}
